<?php use App\Domain\Returns\ReturnRules as Rules;$r=$return;$selectedAction=$selectedAction??''; ?>
<div class="deliveries-editor deliveries-detail"><section class="admin-page-head"><div><p class="admin-kicker">DEVOLUCIÓN · <?= e(Rules::STATUSES[$r['status']]) ?></p><h1><?= e($r['folio']) ?></h1><p><?= e($r['counterparty_name'].' · '.$r['branch_name']) ?></p></div><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/returns">Devoluciones</a></section><section class="admin-panel deliveries-summary"><header><h2>Resumen operativo</h2><span class="deliveries-status" data-state="<?= e($r['status']) ?>"><?= e(Rules::STATUSES[$r['status']]) ?></span></header><dl><div><dt>Tipo</dt><dd><?= e(Rules::TYPES[$r['return_type']]) ?></dd></div><div><dt>Documento relacionado</dt><dd><?= e($r['source_reference']) ?></dd></div><div><dt>Cliente o proveedor</dt><dd><?= e($r['counterparty_name']) ?></dd></div><div><dt>Sucursal</dt><dd><?= e($r['branch_name']) ?></dd></div><div><dt>Registró</dt><dd><?= e($r['actor_name']) ?></dd></div><div><dt>Fecha de registro</dt><dd><?= e($r['created_at']) ?> UTC</dd></div><div class="deliveries-field-full"><dt>Motivo</dt><dd><?= e($r['reason']) ?></dd></div></dl><p class="deliveries-note">La autorización no altera inventario. El movimiento se genera exclusivamente al confirmar la recepción o salida física.</p></section>
<section class="admin-panel admin-table-panel deliveries-directory"><header class="deliveries-directory-heading"><div><h2>Mercancía</h2><p>Cantidades y condición declarada.</p></div></header><div class="admin-table-wrap" tabindex="0" role="region" aria-label="Partidas de la devolución"><table class="admin-table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Condición</th><th>Movimiento de inventario</th></tr></thead><tbody><?php foreach($items as$item):?><tr><td data-label="Producto"><div><?= e($item['sku'].' · '.$item['product_name']) ?><small><?= e($item['variant_name']) ?></small></div></td><td data-label="Cantidad"><?= e($item['quantity'].' '.$item['symbol']) ?></td><td data-label="Condición"><?= e(Rules::CONDITIONS[$item['material_condition']]) ?></td><td data-label="Movimiento"><?= $item['inventory_movement_id']?'#'.e($item['inventory_movement_id']):'Sin movimiento' ?></td></tr><?php endforeach?></tbody></table></div></section>
<?php foreach(Rules::ACTIONS as$action=>$label):if(!($actions[$action]??false))continue;try{Rules::transition($r['return_type'],$r['status'],$action);}catch(Throwable){continue;}if($selectedAction!==$action):?><a class="deliveries-action-link" data-admin-form-link href="/admin/returns/detail?id=<?= e($r['id']) ?>&amp;action=<?= e($action) ?>"><strong><?= e($label) ?></strong><span aria-hidden="true">→</span></a><?php continue;endif?><section class="admin-panel deliveries-action-panel"><div class="admin-panel-head"><h2><?= e($label) ?></h2><a class="deliveries-text-link" data-admin-form-link href="/admin/returns/detail?id=<?= e($r['id']) ?>">Volver al detalle</a></div><form method="post" action="/admin/returns/action" class="admin-form"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($r['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($r['lock_version']) ?>"><input type="hidden" name="operation_key" value="<?= e(bin2hex(random_bytes(20))) ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><label class="admin-field deliveries-field-full"><span>Observaciones <?= in_array($action,['reject','cancel'],true)?'(obligatorias)':'(opcionales)' ?></span><textarea name="notes" maxlength="500" <?= in_array($action,['reject','cancel'],true)?'required minlength="5"':'' ?>></textarea></label><?php if(in_array($action,['receive','dispatch','cancel'],true)):?><label class="deliveries-confirm"><input type="checkbox" name="physical_confirmation" value="1" required> <?= e($action==='receive'?'Confirmo que la mercancía fue recibida físicamente y que su condición fue revisada.':($action==='dispatch'?'Confirmo que la mercancía salió físicamente hacia el proveedor.':'Confirmo que no se realizó ningún movimiento físico.')) ?></label><?php endif?><button class="admin-primary-button"><?= e($label) ?></button></form></section><?php endforeach?>
<?php if($history):?><section class="admin-panel deliveries-history"><h2>Historial</h2><ol><?php foreach($history as$event):?><li><strong><?= e((Rules::ACTIONS+['create'=>'Devolución registrada'])[$event['action']]??$event['action']) ?></strong> · <?= e($event['actor_name']) ?> · <?= e($event['created_at']) ?> UTC · <?= e(Rules::STATUSES[$event['to_status']]??$event['to_status']) ?><p><?= e($event['notes']) ?><?php if($event['quantity']):?> · <?= e($event['quantity']) ?><?php endif?><?php if($event['inventory_movement_id']):?> · Movimiento #<?= e($event['inventory_movement_id']) ?><?php endif?></p></li><?php endforeach?></ol></section><?php endif?><section class="admin-panel"><p>El material dañado o pendiente de inspección queda trazado, pero no aumenta la existencia disponible. Esta operación no genera reembolsos, notas de crédito ni cambios fiscales.</p></section></div>
